ROW.COLUMN:
select n.Ntwrk_Id, n.Link_Ct, min(k.node_bus_id) as Prmry_Node, row_number() over (partition by n.ntwrk_id order by n.link_ct desc, min(k.node_bus_id) asc) row_num from (select ntwrk_id, node_id, count(1) link_ct from (select lts.first_node_id node_id, nw.ntwrk_id from @MANTAS@.KDD_link_type_summary lts inner join @MANTAS@.KDD_ntwrk nw on nw.ntwrk_id=lts.ntwrk_id inner join @MANTAS@.KDD_link_anlys_ntwrk_defn def on def.ntwrk_defn_id=nw.ntwrk_defn_id where def.ntwrk_defn_nm= 'ML_NETACENCU_NTWRK' and trunc(nw.creat_ts) = (select trunc(cal.clndr_dt) from @MANTAS@.KDD_cal cal where cal.clndr_nm = 'SYSCAL' and cal.clndr_day_age = 0) -- batch name verification and ((@Include_Batch_Verification = 'Y' and nw.PRCSNG_BATCH_NM = (select prcsng_batch_nm from @MANTAS@.KDD_prcsng_batch_control)) OR (@Include_Batch_Verification = 'N') )
UNION ALL select lts.scnd_node_id node_id, nw.ntwrk_id from @MANTAS@.KDD_link_type_summary lts inner join @MANTAS@.KDD_ntwrk nw on nw.ntwrk_id=lts.ntwrk_id inner join @MANTAS@.KDD_link_anlys_ntwrk_defn def on def.ntwrk_defn_id=nw.ntwrk_defn_id where def.ntwrk_defn_nm= 'ML_NETACENCU_NTWRK' and trunc(nw.creat_ts) = (select trunc(cal.clndr_dt) from @MANTAS@.KDD_cal cal where cal.clndr_nm = 'SYSCAL' and cal.clndr_day_age = 0) -- batch name verification and ((@Include_Batch_Verification = 'Y' and nw.PRCSNG_BATCH_NM = (select prcsng_batch_nm from @MANTAS@.KDD_prcsng_batch_control)) OR (@Include_Batch_Verification = 'N') )
) group by ntwrk_id,node_id ) n, @MANTAS@.KDD_NODE k, @MANTAS@.KDD_link_anlys_type_cd t where n.node_id = k.node_id and t.TYPE_ID = k.NODE_TYPE_CD and t.type_nm = 'ACCOUNT' group by n.ntwrk_id, n.link_ct
